settings.custom_liquid:
{%- assign tb_lang = request.locale.iso_code | slice: 0, 2 -%}
{%- if tb_lang == 'en' -%}
  {%- assign tb1 = 'Free shipping' -%}{%- assign tb2 = 'Risk-free' -%}{%- assign tb3 = 'Secure checkout' -%}{%- assign tb4 = 'USB plug & play' -%}
{%- elsif tb_lang == 'pt' -%}
  {%- assign tb1 = 'Frete grátis' -%}{%- assign tb2 = 'Compra sem risco' -%}{%- assign tb3 = 'Pagamento seguro' -%}{%- assign tb4 = 'USB plug & play' -%}
{%- else -%}
  {%- assign tb1 = 'Envío gratis' -%}{%- assign tb2 = 'Compra sin riesgo' -%}{%- assign tb3 = 'Pago seguro' -%}{%- assign tb4 = 'USB plug & play' -%}
{%- endif -%}
<div class="su-tb">
  <div class="su-tb__item"><span>🚚</span><b>{{ tb1 }}</b></div>
  <div class="su-tb__item"><span>🛡️</span><b>{{ tb2 }}</b></div>
  <div class="su-tb__item"><span>🔒</span><b>{{ tb3 }}</b></div>
  <div class="su-tb__item"><span>🔌</span><b>{{ tb4 }}</b></div>
</div>
<style>
.su-tb{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:16px 0 4px;}
.su-tb__item{display:flex;flex-direction:column;align-items:center;text-align:center;gap:5px;padding:11px 6px;border:1px solid #eaddcf;border-radius:12px;background:#fff8f1;}
.su-tb__item span{font-size:1.45rem;line-height:1;}
.su-tb__item b{font-size:.72rem;color:#6b4a3a;font-weight:600;line-height:1.2;}
@media(max-width:600px){.su-tb{grid-template-columns:repeat(2,1fr);}}
</style>
